func DispatchStateObserver(d, p, m byte, vec *StateVector) error {
	identity, err := ResolveStateObserverIdentity(d, p, m)
	if err != nil {
		return err
	}
	handler := StateObserverTable[identity.Code]
	if handler == nil {
		return errors.New("stateobserver kernel not initialized")
	}
	return handler(identity, vec)
}

func GetStateObserverExecutionCount(code uint16) uint64 {
	if code >= 1000 {
		return 0
	}
	return atomic.LoadUint64(&StateObserverMetrics[code])
}
